  async function deleteCloudAccount(){if(!supabaseClient||!saved.account)return;const typed=prompt(`Permanently delete “${saved.account.username}”? Type DELETE to confirm.`);if(typed!=='DELETE')return;const button=ui.settingsContent.querySelector('[data-delete-account]');if(button)button.disabled=true;const {error}=await supabaseClient.rpc('delete_my_account');if(error){if(button)button.disabled=false;alert(`Account deletion failed: ${cloudUnavailable(error)}`);return;}await supabaseClient.auth.signOut();saved.account=null;saved.friendRequests=false;currentAuthUser=null;save();ui.settingsModal.classList.add('hidden');ui.startScreen.classList.add('hidden');ui.deviceScreen.classList.add('hidden');ui.authScreen.classList.remove('hidden');setAuthMode('login');authStatus('Account permanently deleted. Its exact username is available again.');}
