  function setCreatorTool(tool){creator.tool=tool;document.querySelectorAll('[data-creator-tool]').forEach(b=>b.classList.toggle('active',b.dataset.creatorTool===tool));const hints={path:'Click points to make the enemy path. The entrance and Heartwood connect to the edges automatically.',obstacle:'Click the map to add an obstacle.',range:'Click the map to add a range buff.',damage:'Click the map to add a damage buff.',trap:'Click the map to add a slow trap.'};ui.creatorHint.textContent=hints[tool]||'Choose where to add the special.';}
  function parseWavePlan(text){const plan={};for(const line of text.split(/\n+/)){const [wavePart,rosterPart]=line.split(':');const wave=Number(wavePart?.trim());if(!wave||!rosterPart)continue;const roster={};for(const item of rosterPart.split(',')){const [type,count]=item.split('=').map(x=>x.trim());if(type&&Number(count)>0)roster[type]=Math.min(999,Math.floor(Number(count)));}if(Object.keys(roster).length)plan[wave]=roster;}return plan;}
  function parseCustomUnits(text,kind){const output={};for(const line of text.split(/\n+/)){const parts=line.split('|').map(x=>x.trim()),id=parts.shift()?.toLowerCase().replace(/[^a-z0-9_]/g,'');if(!id||parts.length<2)continue;const color=parts.shift()||'#ffffff',values={};for(const part of parts){const [key,...rest]=part.split(/\s+/);values[key.toLowerCase()]=rest.join(' ');}if(kind==='enemy')output[id]={name:id.replaceAll('_',' '),color,hp:Number(values.hp)||1,speed:Number(values.speed)||1,reward:Number(values.reward)||1,leakDamage:Number(values.damage)||20,ability:values.ability||'Custom map enemy',description:values.description||'Created by the map designer.'};else output[id]={label:id.replaceAll('_',' '),color,cost:Number(values.cost)||80,damage:Number(values.damage)||20,range:Number(values.range)||135,rate:Number(values.rate)||1,desc:values.description||'Custom map tower'};}return output;}
