  function creatorPaint(e,record=false){const r=ui.creatorCanvas.getBoundingClientRect(),p={x:Math.round((e.clientX-r.left)*960/r.width),y:Math.round((e.clientY-r.top)*560/r.height)},brush=creator.tool==='path'?0:creator.tool==='obstacle'?34:creator.tool==='trap'?28:65,last=creator.tool==='path'?creator.path.at(-1):creator.tool==='obstacle'?creator.obstacles.at(-1):creator.tool==='trap'?creator.traps.at(-1):creator.zones.at(-1);if(last&&Math.hypot(p.x-last.x,p.y-last.y)<Math.max(25,brush))return;if(record)recordCreatorChange();if(creator.tool==='path')creator.path.push(p);else if(creator.tool==='obstacle')creator.obstacles.push({...p,r:brush,artId:selectedDrawingFor('obstacle')?.id});else if(creator.tool==='trap')creator.traps.push({...p,r:brush,artId:selectedDrawingFor('trap')?.id});else creator.zones.push({...p,r:brush,type:creator.tool,artId:selectedDrawingFor(creator.tool)?.id});creatorDrawing=false;drawCreator();updateCreatorHistoryButtons();}
